content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体审查",
            "criterion": "核实签约主体合法性与信息一致性",
            "check_points": [
                "通过国家企业信用信息公示系统或司法大数据平台核查该主体是否存在未结重大涉诉、被执行、失信、严重违法等情形",
                "核对营业执照登记的经营范围，确认合同标的（如软件采购）属于其许可或一般经营项目范围内",
                "比对合同载明的主体信息（名称、统一社会信用代码、注册地址、联系地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "如涉及软件等技术产品采购，核查卖方是否拥有该产品的核心知识产权（如著作权登记证书、专利证书、授权链条文件），或明确约定知识产权归属及使用权限"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架完整性审查",
            "criterion": "确保合同必备条款齐全、结构清晰、权责明确",
            "check_points": [
                "检查是否完整涵盖以下核心条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用限制、产品质量/服务标准及保证、交付方式与地点、验收标准与流程、完成时限（含里程碑节点）、违约责任（含违约金计算方式与上限）、争议解决方式（司法管辖或仲裁）、不可抗力定义与处理机制、廉洁承诺条款、合同变更程序、合同份数及效力说明、电子送达效力约定",
                "确认合同中已明确指定主要项目负责人，并完整列明其姓名、身份证号码（或统一社会信用代码）、联系电话及职责范围",
                "核查采购内容是否具体化：品种、规格、型号、等级、花色等要素是否逐一列明；若内容复杂，是否通过附件（如技术规格书、配置清单）予以详述且附件已签字盖章确认",
                "核验合同金额表述：数量单位、单价、总价、币种（如人民币/USD）是否准确无误；大小写金额是否一致；是否明确计价依据（如含税/不含税）、税率及税种",
                "审查付款计划：是否设置与履约进度挂钩的明确付款节点（如预付款、到货款、初验款、终验款、质保金）；质保金比例是否合理（通常不低于5%），是否约定于免费维保期届满后支付；是否注明各期付款对应发票类型（增值税专用发票/普通发票）及开票时限"
            ]
        },
        {
            "id": "C3",
            "section": "合同期限与时间表述审查",
            "criterion": "确保期限约定精确、无歧义，符合实务操作要求",
            "check_points": [
                "合同期限是否以起止日期（年/月/日）明确标定，或采用‘自××年××月××日起至××年××月××日止’的封闭式表述",
                "若按周期（年度/季度/月/旬/日）计算，是否明确定义计算基准（如‘自然日’或‘工作日’；‘自然季度’或‘自起始日起每满三个月为一个季度’）",
                "关键时间节点（如交付日、验收日、付款日、质保期起算日）是否与合同期限逻辑自洽，是否存在倒挂或冲突"
            ]
        },
        {
            "id": "C4",
            "section": "文本规范性与一致性审查",
            "criterion": "保障合同语言严谨、格式统一、内容无矛盾",
            "check_points": [
                "全文通读排查错别字、标点误用、语法错误、语义不清或逻辑矛盾等文字性瑕疵",
                "核对正文与所有附件（技术协议、服务清单、报价明细等）中相同条款（如验收标准、付款条件、知识产权归属）的表述是否完全一致，是否存在冲突",
                "清理招标、谈判、询价等采购流程中的阶段性用语（如‘投标单位’‘谈判小组’‘响应文件’），统一替换为合同签署语境下的规范表述（如‘乙方’‘甲方’‘本合同’）",
                "逐字比对合同首部‘甲方/乙方’全称、签约页落款主体名称、印章名称三者是否严格一致（包括括号、空格、简称与全称混用等细节）",
                "核查所援引法律法规（如《民法典》第××条、《著作权法》第××条）是否现行有效，条款序号与最新修订版本一致",
                "确认合同正文末尾是否规范标注‘以下为合同签署栏’或‘以下无正文’字样，且该行之后无实质性内容"
            ]
        }
    ]
}
